/**
 * SLATE — the high streets that were leaning on somebody else's chains.
 *
 * The coverage tool has always printed the unevenness rather than hiding it,
 * and what it printed was 63 markets with fewer than ten chains of their own
 * and 36 that could not supply food, clothes and a television without a
 * worldwide chain doing the work. A player living in Hanoi or Lagos or
 * Santiago found a high street that was technically real and felt borrowed.
 *
 * This is the local half. Every chain here is a real company trading in the
 * markets listed against it, named as public record. Where a chain really is
 * regional it is listed in every country it really trades in, and where it is
 * one country's own it is listed in that one.
 *
 * What is SLATE's, and says so on every row as it always has: whether there
 * is a branch in this particular city, what is on the shelf, and what it
 * costs. No company publishes its store list as data anybody can license, so
 * placement is a calibration and is labeled as one.
 *
 * A note on what is deliberately absent. Chains that have closed or pulled
 * out of a market are not here, because a shop you cannot walk into is not
 * coverage: Nakumatt and Tuskys in Kenya, Justo & Bueno in Colombia, and the
 * many Western chains that left Russia in 2022 are all left out on purpose.
 */

import { REFERENCE_VERSION } from './reference';
import type { RealRetailer } from './brands';

const REAL = {
  source: 'public_reference', confidence: 'high', version: REFERENCE_VERSION,
  note: 'Real company, named as public record. Branch placement, stock and prices are SLATE\'s own.',
} as const;

type Spec = Omit<RealRetailer, 'type' | 'source' | 'confidence' | 'version' | 'note'>;
const shop = (spec: Spec): RealRetailer => ({ ...spec, markets: [...new Set(spec.markets)], type: 'retailer', ...REAL });

/** Shorthand, because these rows are mostly the same shape. */
const g = (id: string, name: string, markets: string[], tier: 1 | 2 | 3 | 4 | 5, mult: number, min: number, description: string, extra: string[] = []): RealRetailer =>
  shop({ id, name, kind: 'grocery', tier, priceMultiplier: mult, categories: ['groceries', 'household', ...extra], markets, minimumCity: min, online: true, deliveryDays: 2, description });
const c = (id: string, name: string, markets: string[], mult: number, description: string): RealRetailer =>
  shop({ id, name, kind: 'convenience', tier: 2, priceMultiplier: mult, categories: ['groceries', 'prepared'], markets, minimumCity: 5_000, online: false, deliveryDays: 0, description });
const e = (id: string, name: string, markets: string[], tier: 1 | 2 | 3 | 4 | 5, mult: number, min: number, description: string): RealRetailer =>
  shop({ id, name, kind: 'electronics', tier, priceMultiplier: mult, categories: ['electronics', 'appliance'], markets, minimumCity: min, online: true, deliveryDays: 3, description });
const h = (id: string, name: string, markets: string[], tier: 1 | 2 | 3 | 4 | 5, mult: number, min: number, description: string, extra: string[] = []): RealRetailer =>
  shop({ id, name, kind: 'highstreet', tier, priceMultiplier: mult, categories: ['clothing', 'footwear', 'accessory', ...extra], markets, minimumCity: min, online: true, deliveryDays: 3, description });
const d = (id: string, name: string, markets: string[], tier: 1 | 2 | 3 | 4 | 5, mult: number, min: number, description: string): RealRetailer =>
  shop({ id, name, kind: 'department', tier, priceMultiplier: mult, categories: ['clothing', 'footwear', 'accessory', 'home', 'household'], markets, minimumCity: min, online: true, deliveryDays: 3, description });
const p = (id: string, name: string, markets: string[], mult: number, min: number, description: string): RealRetailer =>
  shop({ id, name, kind: 'pharmacy', tier: 2, priceMultiplier: mult, categories: ['pharmacy', 'household'], markets, minimumCity: min, online: true, deliveryDays: 2, description });

